------------------------------------------------
 

CREATE TABLE "DBA     "."DIREITOS_PROCESSOS"  (
		  "IDPROCESSO" INTEGER NOT NULL , 
		  "IDUSUARIO" INTEGER NOT NULL , 
		  "FLAGINSERE" CHAR(1) NOT NULL WITH DEFAULT 'F' , 
		  "FLAGALTERA" CHAR(1) NOT NULL WITH DEFAULT 'F' , 
		  "FLAGDELETA" CHAR(1) NOT NULL WITH DEFAULT 'F' , 
		  "FLAGCONSULTA" CHAR(1) NOT NULL WITH DEFAULT 'F' , 
		  "FLAGCONFIGURA" CHAR(1) NOT NULL WITH DEFAULT 'F' , 
		  "FLAGLIGADO" CHAR(1) NOT NULL WITH DEFAULT 'F' , 
		  "DTALTERACAO" TIMESTAMP , 
		  "FLAGLIBERASOLICITA" CHAR(1) NOT NULL WITH DEFAULT 'F' , 
		  "FLAGLIBERADETALHES" CHAR(1) NOT NULL WITH DEFAULT 'F' , 
		  "TIPOLIBERACAO" CHAR(1) NOT NULL WITH DEFAULT 'A' , 
		  "TIPOLOCALLIBERACAO" CHAR(1) WITH DEFAULT 'A' , 
		  "OBSPADRAO" VARCHAR(400) WITH DEFAULT '' )   
		 COMPRESS YES ADAPTIVE  
		 IN "USERSPACE1" LONG IN "LOBSPACE1"  
		 ORGANIZE BY ROW; 

COMMENT ON TABLE "DBA     "."DIREITOS_PROCESSOS" IS 'Entidade que armazena todos os direitos dos usuarios a nivel de excessao.';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."DTALTERACAO" IS 'Campo responsavel para identificar o DateTimee da alteracao dos dados do registro na tabela. ';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."FLAGALTERA" IS 'Flag que identifica se o usuario podera alterar ou nao determinado objeto. DEFAULT (F)';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."FLAGCONFIGURA" IS 'Flag que identifica se o usuario podera configurarr ou nao determinado objeto. DEFAULT (F)';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."FLAGCONSULTA" IS 'Flag que identifica se o usuario podera cinsultar  ou nao determinado objeto. DEFAULT (F)';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."FLAGDELETA" IS 'Flag que identifica se o usuario podera deletar ou no determinado objeto. DEFAULT (F)';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."FLAGINSERE" IS 'Flag que identifica se o usuario podera inserir ou nao determinado objeto. DEFAULT (T)';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."FLAGLIBERADETALHES" IS 'Determina se o solicitante podera ver os detalhes da solicitacao';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."FLAGLIBERASOLICITA" IS 'Indica que o processo so pode ser liberado na maquina do solicitante.';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."FLAGLIGADO" IS 'Identifica que o processo e verdadeiro caso possua "T"", ou false caso possua "F""';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."IDPROCESSO" IS 'Identificador de codigo do processo.';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."IDUSUARIO" IS 'Codigo do usuario do sistema';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."OBSPADRAO" IS 'Observao padro. Campo ser livre de digitao apresentado em tela no sistema para facilitar orientao';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."TIPOLIBERACAO" IS 'A -Aguardar Liberacao, E - Enviar para Aprovacao';

COMMENT ON COLUMN "DBA     "."DIREITOS_PROCESSOS"."TIPOLOCALLIBERACAO" IS 'Local ativo para liberao A - Ambos, P - Ciss Process, C - Ciss Poder';


