COMMENT ON TABLE "DBA     "."CONTAS_RECEBER_MAGNETICO" IS 'Tabela auxiliar que contem dados complementares qdo a duplicata foi manda via meio magnetico para o banco. os attributos serao gravados com o valores default vindos da tabela de bancos. Tendo a possibilidade do usuario alterar qdo necessario.';

COMMENT ON COLUMN "DBA     "."CONTAS_RECEBER_MAGNETICO"."CARTEIRACOBRANCA" IS 'Identifica de acordo com o  banco qual sera o tipo de cobranca a ser realizada. Obs Os codigos variam conforme o banco';

COMMENT ON COLUMN "DBA     "."CONTAS_RECEBER_MAGNETICO"."CODIGOCOMANDO" IS 'Codigo de comando que idenfica qual a operacao a ser realizada pelo banco com o titulo em operacoes normais de envio. Nos casos de uma operacao especial este codigo de comando sera alterado diretamente no titulo.';

