COMMENT ON COLUMN "DBA     "."CONTAS_RECEBER_MAGNETICO"."INSTRUCAO01" IS 'Codigo da instrucao para o banco. que impresso no bloqueto. Varia de acordo com o banco EX.: 01 - Protestar em NN dias';

COMMENT ON COLUMN "DBA     "."CONTAS_RECEBER_MAGNETICO"."INSTRUCAO02" IS 'Codigo da instrucao para o banco. que impresso no bloqueto. Varia de acordo com o banco EX.: 02 - Nao receber apos nn dias enviar p/ cartorio.';

COMMENT ON COLUMN "DBA     "."CONTAS_RECEBER_MAGNETICO"."NOSSONUMERO" IS 'Contador referente ao nosso numero.(Qdo a empresa emite seus proprios bloquetos e o banco aceita esta sequencia de numeracao como valido).';

COMMENT ON COLUMN "DBA     "."CONTAS_RECEBER_MAGNETICO"."NUMEROBORDERO" IS 'Numero do lote de bordero para cada malote enviado';

