		  "FORMULACTOULTCOMPRA" CLOB(1048576) LOGGED NOT COMPACT , 
		  "FORMULACTONOTAFISCAL" CLOB(1048576) LOGGED NOT COMPACT , 
		  "FORMULASUGVAREJO" CLOB(1048576) LOGGED NOT COMPACT , 
		  "FORMULAVALORLUCRO" CLOB(1048576) LOGGED NOT COMPACT , 
		  "FORMULAMARGEMVAREJO" CLOB(1048576) LOGGED NOT COMPACT , 
		  "FORMULAMARGEMATACADO" CLOB(1048576) LOGGED NOT COMPACT , 
		  "FORMULASUGATACADO" CLOB(1048576) LOGGED NOT COMPACT , 
		  "FORMULACTOREPOSICAO" CLOB(1048576) LOGGED NOT COMPACT , 
		  "TIPOFORMULA" CHAR(1) , 
		  "FLAGVALCUSTOSCOMPLEMGERADO" CHAR(1) WITH DEFAULT 'F' , 
		  "DTALTERACAO" TIMESTAMP , 
		  "IDEMPRESA" INTEGER , 
		  "FORMULAMARGEMVAREJOREPOSICAO" CLOB(1048576) LOGGED NOT COMPACT )   
		 COMPRESS YES ADAPTIVE  
		 IN "USERSPACE1" LONG IN "LOBSPACE1"  
		 ORGANIZE BY ROW; 

