COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."DTALTERACAO" IS 'Data/hora da alteracao';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."FLAGVALCUSTOSCOMPLEMGERADO" IS 'Default "F"", qdo o usar trocar o tipo de formulas para Valores, o sistema ira sentir e roda um processo de geracao de valores para a tabela movimento_custo. No final valor volta a ser "T""';

