COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."FORMULACTONOTAFISCAL" IS 'Formula do custo da nota fiscal';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."FORMULACTOREPOSICAO" IS 'Formula da sugestao de custo reposicao.';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."FORMULACTOULTCOMPRA" IS 'Formula do custo da ultima compra';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."FORMULAMARGEMATACADO" IS 'Formula para sugestao de preco atacado';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."FORMULAMARGEMVAREJO" IS 'Formula da margem de lucro varejo, sugestao de preco';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."FORMULAMARGEMVAREJOREPOSICAO" IS 'Formula da margem de lucro varejo com base no custo reposicao';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."FORMULASUGATACADO" IS 'Formula da sugestao de preco para atacado';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."FORMULASUGVAREJO" IS 'Formula da sugestao de preco para varejo';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."FORMULAVALORLUCRO" IS 'Formula do retorno do valor do lucro';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."IDEMPRESA" IS 'Empresa que a formula e aplicada';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."IDFORMULA" IS 'Codigo de identificacao da formula';

COMMENT ON COLUMN "DBA     "."FORMULA_PRECOS"."TIPOFORMULA" IS 'Indica se a margem de lucro e sugestao de preco e calculada sobre custo ou sobre venda (V - venda, C - custo)';


