		  "DTHORASOLICITACAO" TIMESTAMP , 
		  "IDEMPRESA" INTEGER , 
		  "IDCLIFOR" INTEGER , 
		  "TIPOSITUACAO" CHAR(1) , 
		  "TEXTO" CLOB(1048576) LOGGED NOT COMPACT , 
		  "MENSAGEMRETORNO" VARCHAR(600) , 
		  "IDPLANILHA" INTEGER , 
		  "IPSOLICITANTE" CHAR(15) , 
		  "IDVENDEDOR" INTEGER , 
		  "DTHORAEFETIVACAO" TIMESTAMP WITH DEFAULT NULL )   
