		 ORGANIZE BY ROW; 

COMMENT ON TABLE "DBA     "."LOG_SOLICITACOES_LIBERACAO" IS 'Guarda movimenta??es de solicitaes de libera??es de precessos do sistema em geral';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."CHAVEPESQUISA" IS 'Chave utilizada para diferenciar uma solicitacao de liberacao duplicada Ex.: Na mesma nota ou seja no mesmo idsolicitacao havera varias solicitacoes como descontos em varios itens, que deverao ser consideradas como individuais';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."DTHORAEFETIVACAO" IS 'Indica a data e hora que a solicitacao foi aprovada/desaprovada';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."DTHORASOLICITACAO" IS 'Data e hora que foi realizada a solicitacao';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."IDCLIFOR" IS 'Codigo de identificacao do cadastro cliente/fornecedor/vendedor/transportador. Obs.: O IDCLIFOR devera ser composto pelo codigo da filial que esta cadastrando + contador auto-incremento.';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."IDEMPRESA" IS 'Identificador do codigo da empresa';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."IDPLANILHA" IS 'Planilha de identificacao do lcto que foi liberado';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."IDPROCESSO" IS 'Identificador de codigo do processo.';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."IDSOLICITACAO" IS 'Contador da Solicitacao.';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."IDUSUARIOLIBERACAO" IS 'Codigo do usuario do sistema';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."IDUSUARIOSOLICITANTE" IS 'Codigo do usuario do sistema';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."IDVENDEDOR" IS 'Identificacao do vendedor, utilizado nos processos de frente de caixa e retaguarda';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."IPSOLICITANTE" IS 'Ip da maquina solicitante da liberacao';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."MENSAGEMRETORNO" IS 'Mensagem informada pelo usuario que liberou ou bloqueou a solicitacao. exemplo: Bloqueio Bloqueado em funcao de ser um inadimplente irrecuperavel. Exemplo: Liberado Pode vender, mais a entrega sera feita somente a noite.';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."ORIGEMMOVIMENTO" IS 'Abreviatura da origem do lancamento';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."TEXTO" IS 'Observacao sobre a solicitacao de liberacao do processo exemplo: Caso de descontos: Dados do cliente, valor do produtos valor do desconto etc...';

COMMENT ON COLUMN "DBA     "."LOG_SOLICITACOES_LIBERACAO"."TIPOSITUACAO" IS 'Identifica se a solicitacao foi liberada pelo usuario solicitado ou nao: " " - que ainda nao obteve resposta do usuario liberacao; "S" - Liberacao efetuada; "N" - Liberacao nao liberada.';


