COMMENT ON COLUMN "DBA     "."LAYOUT_CHEQUE"."FLAGMEIALINEXTENSO1" IS '""T" Indica se avancara meia linha apos imprimir o extenso1';

COMMENT ON COLUMN "DBA     "."LAYOUT_CHEQUE"."FLAGMEIALINEXTENSO2" IS '""T" Indica se avancara meia linha apos imprimir o extenso 2';

COMMENT ON COLUMN "DBA     "."LAYOUT_CHEQUE"."FLAGMEIALINFAVORECIDO" IS '""T" Indica se avancara meia linha apos imprimir o Favorecido';

COMMENT ON COLUMN "DBA     "."LAYOUT_CHEQUE"."FLAGMEIALINPREDATADO" IS '""T" Indica se avancara meia linha apos imprimir predatato';

COMMENT ON COLUMN "DBA     "."LAYOUT_CHEQUE"."FLAGMEIALINVALOR" IS '""T" Indica se avancara meia linha apos imprimir o valor';

