COMMENT ON COLUMN "DBA     "."LAYOUT_CHEQUE"."NUMLINEXTENSO2" IS 'Numero da linha que sera impressa a segunda parte do extenso do cheque';

COMMENT ON COLUMN "DBA     "."LAYOUT_CHEQUE"."NUMLINFAVORECIDO" IS 'Numero da linha que sera impresso  o nome do favorecido do cheque.';

COMMENT ON COLUMN "DBA     "."LAYOUT_CHEQUE"."NUMLINPREDATADO" IS 'Numero da linha que sera impresso  a data que o cheque foi pre-datado.';

COMMENT ON COLUMN "DBA     "."LAYOUT_CHEQUE"."NUMLINVALOR" IS 'Numero da linha que sera impresso o valor do cheque';

COMMENT ON COLUMN "DBA     "."LAYOUT_CHEQUE"."NUMTAMEXTENSO1" IS 'Tamanho da string que sera impresso na linha de extenso 1';

COMMENT ON COLUMN "DBA     "."LAYOUT_CHEQUE"."NUMTAMEXTENSO2" IS 'Tamanho da string que sera impresso na linha de extenso 2';


