COMMENT ON COLUMN "DBA     "."CONFIG_OUTRAS_FRENTES"."T05" IS 'Legenda de tributacao para conversao da tributacao do sistema para a tributacao do software da frente de caixa Ex:  T05 = I  Isento no sistema';

