-- Instruções DDL para Tabela "DBA     "."FLUXO_CAIXA"
------------------------------------------------
 

CREATE TABLE "DBA     "."FLUXO_CAIXA"  (
		  "IDFLUXO" INTEGER NOT NULL GENERATED ALWAYS AS IDENTITY (  
		    START WITH +1  
		    INCREMENT BY +1  
		    MINVALUE +1  
		    MAXVALUE +2147483647  
		    NO CYCLE  
		    CACHE 20  
		    NO ORDER ) , 
		  "IDEMPRESA" INTEGER NOT NULL , 
		  "IDPLANILHA" INTEGER NOT NULL , 
		  "NUMSEQUENCIA" INTEGER NOT NULL , 
		  "IDCTAFLUXO" INTEGER NOT NULL , 
		  "DTFLUXO" DATE NOT NULL , 
		  "TIPOFLUXO" CHAR(1) NOT NULL , 
		  "TIPONATUREZALCTO" CHAR(1) NOT NULL , 
		  "IDCLIFOR" INTEGER , 
		  "IDCTAORIGEM" INTEGER , 
		  "VALOR" DECIMAL(14,2) WITH DEFAULT 0 , 
		  "DTMOVIMENTO" DATE , 
		  "ORIGEMMOVIMENTO" VARCHAR(6) , 
		  "IDUSUARIOCONCILIACAO" INTEGER , 
		  "IDFLUXOPREVISAO" INTEGER , 
		  "IDFLUXOORIGEM" INTEGER , 
		  "DTVENCIMENTO" DATE , 
		  "COMPLEMENTO" VARCHAR(300) , 
		  "TIPOCONCILIADO" CHAR(1) , 
		  "IDNUMCHEQUE" INTEGER , 
		  "IDPEDIDO" INTEGER , 
		  "VALCONCILIADO" DECIMAL(14,2) WITH DEFAULT 0 , 
		  "FLAGFLUXO" CHAR(1) WITH DEFAULT 'F' , 
		  "VALREALIZADO" DECIMAL(14,2) WITH DEFAULT 0 )   
		 COMPRESS YES ADAPTIVE  
		 IN "USERSPACE1" LONG IN "LOBSPACE1"  
		 ORGANIZE BY ROW; 

COMMENT ON TABLE "DBA     "."FLUXO_CAIXA" IS 'Registros de fluxo de caixa financeiro';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."COMPLEMENTO" IS 'Texto de observacao/complemento';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."DTFLUXO" IS 'Data/Hora para controle interno do sistema/aplicativo';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."DTMOVIMENTO" IS 'Data de movimento - data em que o registro e valido, nao necessariamente e a data de inclusao do registro';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."DTVENCIMENTO" IS 'Data de fluxo original/vencimento dos titulos';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."FLAGFLUXO" IS 'Identifica se o registro ira aparecer no fluxo de caixa';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."IDCLIFOR" IS 'Codigo de identificacao do cadastro cliente/fornecedor/vendedor/transportador. Obs.: O IDCLIFOR deverao ser composto pelo codigo da filial que esta cadastrando + contador auto-incremento.';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."IDCTAFLUXO" IS 'Conta contabil';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."IDCTAORIGEM" IS 'Conta contabil';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."IDEMPRESA" IS 'Identificador da empresa';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."IDFLUXO" IS 'Codigo interno sequencial da entidade (ver chaves da tabela - PK/FK)';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."IDFLUXOORIGEM" IS 'ID do fluxo que deu origem a este (se houve)';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."IDFLUXOPREVISAO" IS 'Codigo interno sequencial da entidade (ver chaves da tabela - PK/FK)';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."IDNUMCHEQUE" IS 'Numero do cheque emitido ou recebido';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."IDPEDIDO" IS 'Indica a qual pedido de compra o registro pertence';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."IDPLANILHA" IS 'Contador de planilha de movimentacao';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."IDUSUARIOCONCILIACAO" IS 'Codigo do usuario do sistema';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."NUMSEQUENCIA" IS 'Numero de sequencia do registro';

