COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."TIPOCONCILIADO" IS '""E" = Encerrado, "C" = Conciliado ';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."TIPOFLUXO" IS '""P" = Previsao, "E" = Efetivado, "R" = Realizado ';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."TIPONATUREZALCTO" IS 'Natureza do Lancamento    "D" - Debito    "C" - Credito';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."VALCONCILIADO" IS 'Valor monetario';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."VALOR" IS 'Valor monetario';

COMMENT ON COLUMN "DBA     "."FLUXO_CAIXA"."VALREALIZADO" IS 'Valor monetario';


