		    CACHE 20  
		    NO ORDER ) , 
		  "ARQUIVOTEXTO" CLOB(1048576) LOGGED NOT COMPACT , 
		  "TELAERRO" BLOB(1048576) LOGGED NOT COMPACT )   
		 COMPRESS YES ADAPTIVE  
		 IN "USERSPACE1" LONG IN "LOBSPACE1"  
		 ORGANIZE BY ROW; 

