		  "IDEMPRESABAIXA" INTEGER , 
		  "DTPAGAMENTO" DATE , 
		  "VALPAGAMENTOTITULO" DECIMAL(14,2) WITH DEFAULT 0 , 
		  "VALJUROSCOBRADO" DECIMAL(14,2) WITH DEFAULT 0 , 
		  "VALDESCCONCEDIDOTITULO" DECIMAL(14,2) WITH DEFAULT 0 , 
		  "VALJUROSISENTADO" DECIMAL(14,2) WITH DEFAULT 0 , 
		  "VALJUROSPOSTERGADO" DECIMAL(14,2) WITH DEFAULT 0 , 
