		 ORGANIZE BY ROW; 

COMMENT ON TABLE "DBA     "."CONTAS_PAGAR_BAIXAS" IS 'Entidade que armazena os lctos da Nota/ duplicata, originados pelo contas a pagar.';

COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."DIGITOTITULO" IS 'Digito que identifica o desdobramento da duplicata.';

COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."DTALTERACAO" IS 'Data de alteracao do registro';

COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."DTPAGAMENTO" IS 'Data de Pagamento da duplicata';

COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."IDCLIFOR" IS 'Codigo de identificacao do cadastro cliente/fornecedor/vendedor/transportador. Obs.: O IDCLIFOR devera ser composto pelo codigo da filial que esta cadastrando + contador auto-incremento.';

COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."IDEMPRESA" IS 'Identificador do codigo da empresa';

COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."IDEMPRESABAIXA" IS 'Identificador do codigo da empresa';

