COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."ORIGEMMOVIMENTO" IS 'Abreviatura da origem do lancamento';

COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."SERIENOTA" IS 'Serie da nota fiscal a qual se refere a duplicata';

COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."VALDESCCONCEDIDOTITULO" IS 'Valor do desconto que foi concedido no pagamento do titulo, o valor original nunca e alterado';

COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."VALJUROSCOBRADO" IS 'Valor dos juros que ja foram cobrados, caso o titulo teve atraso';

COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."VALJUROSISENTADO" IS 'Valor de juros que foram isentados do cliente, em uma negociacao o juros podem ser abonados, para que fique documentado serao gravados neste campo';

COMMENT ON COLUMN "DBA     "."CONTAS_PAGAR_BAIXAS"."VALJUROSPOSTERGADO" IS 'Valor dos juros de mora que nao foram isentados, deverao ser pagos no futuro.';

