		  "TIPOPRAZO" CHAR(1) , 
		  "DTALTERACAO" TIMESTAMP , 
		  "TIPOCONVENIO" CHAR(1) , 
		  "DIAVCTOQUINZ1" INTEGER WITH DEFAULT 0 , 
		  "DIAVCTOQUINZ2" INTEGER WITH DEFAULT 0 , 
		  "DIAVCTOSEM" INTEGER WITH DEFAULT 0 , 
		  "TIPOLIMITE" CHAR(1) NOT NULL WITH DEFAULT 'G' , 
		  "VALMINPARCELAMENTO" DECIMAL(14,2) WITH DEFAULT 0 , 
		  "QTDMAXPARCELA" INTEGER WITH DEFAULT 0 , 
