		 IN "USERSPACE1" LONG IN "LOBSPACE1"  
		 ORGANIZE BY ROW; 

COMMENT ON TABLE "DBA     "."CLIENTE_CONVENIO" IS 'Cnvenios de venda com condies de pgto e descontos diferenciados de uma venda normal.';

COMMENT ON COLUMN "DBA     "."CLIENTE_CONVENIO"."DESCRCONVENIO" IS 'Descricao do Convenio';

COMMENT ON COLUMN "DBA     "."CLIENTE_CONVENIO"."DIAFECHAMENTO" IS 'Dia de fechamento do convenio, usada para encerrar o montante da venda para aquele periodo.';

