COMMENT ON COLUMN "DBA     "."CLIENTE_CONVENIO"."DIAVCTOQUINZ2" IS 'Dia de vencimento na segunda quinzena';

COMMENT ON COLUMN "DBA     "."CLIENTE_CONVENIO"."DIAVCTOSEM" IS 'Dia de vencimento semanal (1 - Domingo, 2 - Segunda, ...)';

