COMMENT ON COLUMN "DBA     "."CLIENTE_CONVENIO"."FLAGFECHAMENTOAUTOMATICO" IS 'Defina se o convenio tera fechamento automatico';

COMMENT ON COLUMN "DBA     "."CLIENTE_CONVENIO"."FLAGFUNCIONARIO" IS 'Identificacao de convenio para funcionarios';

COMMENT ON COLUMN "DBA     "."CLIENTE_CONVENIO"."FLAGZERARLIMITEARQUIVO" IS 'Valida se zera ou nao o limite dos clientes relacionados ao convenio pela tela de "Importacao de Cadastros e Limites de Convenio - UniCooper""';

