-- Instruções DDL para Tabela "DBA     "."PRODUTO_SOLICITACAO_VENDA"
------------------------------------------------
 

CREATE TABLE "DBA     "."PRODUTO_SOLICITACAO_VENDA"  (
		  "NUMSEQUENCIA" INTEGER NOT NULL WITH DEFAULT 0 , 
		  "IDCLIFOR" INTEGER NOT NULL , 
		  "IDPRODUTO" INTEGER , 
		  "IDSUBPRODUTO" INTEGER , 
		  "IDVENDEDOR" INTEGER , 
		  "IDEMPRESA" INTEGER NOT NULL , 
		  "IDUSUARIO" INTEGER , 
		  "QTDSOLICITADA" DECIMAL(12,3) WITH DEFAULT 0 , 
		  "DTLIMITEAVISO" DATE , 
		  "FLAGBAIXADO" CHAR(1) WITH DEFAULT 'F' , 
		  "DTMOVIMENTO" TIMESTAMP , 
		  "OBSERVACAO" CLOB(1048576) LOGGED NOT COMPACT , 
		  "FLAGAVISACLIENTEEMAIL" CHAR(1) WITH DEFAULT 'F' , 
		  "DESCRPRODUTO" VARCHAR(150) , 
		  "IDMOTIVO" INTEGER )   
		 COMPRESS YES ADAPTIVE  
		 IN "USERSPACE1" LONG IN "LOBSPACE1"  
		 ORGANIZE BY ROW; 

COMMENT ON TABLE "DBA     "."PRODUTO_SOLICITACAO_VENDA" IS 'Solicitacao de venda, ou seja se o produto no tem em estoque ou nem mesmo cadastrado, o vendedor pode solicitar a compra cadastrando essa solicitacao';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."DESCRPRODUTO" IS 'Descricao do Produto solicitado';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."DTLIMITEAVISO" IS 'Data limite para aviso (o vendedor sera avisado ate esta data)';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."DTMOVIMENTO" IS 'Data e hora da movimentacao';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."FLAGAVISACLIENTEEMAIL" IS 'Definie se ira avisar o cliente por email quando o produto entrar em estoque';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."FLAGBAIXADO" IS 'Indica se a solicitacao ja foi atendida';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."IDCLIFOR" IS 'Codigo de identificacao do cadastro cliente/fornecedor/vendedor/transportador. Obs.: O IDCLIFOR devera ser composto pelo codigo da filial que esta cadastrando + contador auto-incremento.';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."IDEMPRESA" IS 'Identificador do codigo da empresa';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."IDMOTIVO" IS 'Motivo de perda de Venda';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."IDPRODUTO" IS 'Codigo interno do produto';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."IDSUBPRODUTO" IS 'Codigo do item derivado';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."IDUSUARIO" IS 'Codigo do usuario do sistema';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."IDVENDEDOR" IS 'Codigo de identificacao do cadastro cliente/fornecedor/vendedor/transportador. Obs.: O IDCLIFOR devera ser composto pelo codigo da filial que esta cadastrando + contador auto-incremento.';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."NUMSEQUENCIA" IS 'Identificador da solicitacao';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."OBSERVACAO" IS 'Texto de observacao';

COMMENT ON COLUMN "DBA     "."PRODUTO_SOLICITACAO_VENDA"."QTDSOLICITADA" IS 'Quantidade solicitada';


