------------------------------------------------
 

CREATE TABLE "DBA     "."CHEQUES_MOVIMENTO"  (
		  "IDEMPRESA" INTEGER NOT NULL , 
		  "IDPLANILHACHEQUE" INTEGER NOT NULL , 
		  "IDNUMCHEQUE" INTEGER NOT NULL , 
		  "IDPLANILHA" INTEGER NOT NULL , 
		  "IDCTACONTABIL" INTEGER , 
		  "IDEMPRESAORIGEM" INTEGER , 
		  "IDEMPRESADESTINO" INTEGER , 
		  "IDBANCOCUSTODIA" INTEGER , 
		  "IDUSUARIO" INTEGER , 
		  "ALINEA" VARCHAR(2) , 
		  "DTMOVIMENTO" TIMESTAMP , 
		  "OBSGERAL" VARCHAR(600) , 
		  "TIPOSITUACAO" CHAR(1) , 
		  "VALOR" DECIMAL(14,2) WITH DEFAULT 0 , 
		  "IDPLANILHAMOVTITULO" INTEGER , 
		  "IDCTABANCARIACUSTODIA" INTEGER , 
		  "DTFLUXO" DATE , 
		  "FLAGCOBJUDICIAL" CHAR(1) NOT NULL WITH DEFAULT 'F' , 
		  "VALJUROSCOBRADO" DECIMAL(14,2) WITH DEFAULT 0 , 
		  "FLAGTROCO" CHAR(1) NOT NULL WITH DEFAULT 'F' , 
		  "IDREMESSACUSTODIA" INTEGER )   
		 COMPRESS YES ADAPTIVE  
		 IN "USERSPACE1" LONG IN "LOBSPACE1"  
		 ORGANIZE BY ROW; 

COMMENT ON TABLE "DBA     "."CHEQUES_MOVIMENTO" IS 'Histrico de movimento de cheque (lanamento, liquidao, devoluo, reapresentao, pagamento a terceiros, troca, etc). O registro com o maior valor em DTMOVIMENTO refere-se ao status atual do cheque.';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."ALINEA" IS 'Codigo do motivo que o cheque foi devolvido. Este e um codigo padrao carimbado pelo banco no cheque.';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."DTFLUXO" IS 'COLUNA ALIMENTADA POR TRIGGER';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."DTMOVIMENTO" IS 'Data de movimento do cheque (mudanca de status)';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."FLAGCOBJUDICIAL" IS 'Flag que indica se o cheque esta em cobranca judicial. Somente para cheques devolvidos, transferidos, Cobranca juridica ou Reapresentados';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."FLAGTROCO" IS 'Identifica quando um cheque e fornecido como troco';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDBANCOCUSTODIA" IS 'Codigo Identificador do Banco conforme FEBRABAN';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDCTABANCARIACUSTODIA" IS 'Conta bancaria do sistema utilizada para custodia do cheque';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDCTACONTABIL" IS 'Codigo da conta contabil';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDEMPRESA" IS 'Identificador do codigo da empresa';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDEMPRESADESTINO" IS 'Identificador do codigo da empresa para onde o cheque foi transferido';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDEMPRESAORIGEM" IS 'Identificador da empresa de onde o cheque foi transferido';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDNUMCHEQUE" IS 'Numero do cheque emitido ou recebido';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDPLANILHA" IS 'Identificador de registro global do banco de dados.';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDPLANILHACHEQUE" IS 'Identificador de registro global do banco de dados do momento de lancamento do cheque.';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDPLANILHAMOVTITULO" IS 'Grava planilha utilizada para movimentacao de baixa de titulos a pagar e ou a receber.';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDREMESSACUSTODIA" IS 'Identificador do arquivo de remessa relacionado';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."IDUSUARIO" IS 'Codigo do usuario do sistema que realizou o lancamento';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."OBSGERAL" IS 'Observacao relacionada a mudanca de status do cheque';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."TIPOSITUACAO" IS 'Situacao do cheque';

COMMENT ON COLUMN "DBA     "."CHEQUES_MOVIMENTO"."VALOR" IS 'Valor do lancamento correspondente ao tipo da situacao cheque';


