		  "PERDESCONTO" DECIMAL(14,6) WITH DEFAULT 0 , 
		  "DTALTERACAO" TIMESTAMP , 
		  "TIPODESCONTO" CHAR(1) NOT NULL WITH DEFAULT '1' , 
		  "IDCONTADOR" INTEGER NOT NULL GENERATED ALWAYS AS IDENTITY (  
		    START WITH +84265  
		    INCREMENT BY +1  
		    MINVALUE +84265  
		    MAXVALUE +2147483647  
		    NO CYCLE  
		    CACHE 20  
		    NO ORDER ) , 
		  "IDEMPRESA" INTEGER NOT NULL , 
		  "IDUSUARIO" INTEGER , 
		  "TIPOPRECOATACAREJO" SMALLINT NOT NULL WITH DEFAULT 0 , 
		  "INFOETIQUETA" VARCHAR(30) , 
		  "TIPOSTATUS" CHAR(1) NOT NULL WITH DEFAULT 'A' , 
		  "VALPRECOVAREJO" DECIMAL(15,6) NOT NULL WITH DEFAULT 0 , 
		  "PERDESCONTOATAC" DECIMAL(15,6) WITH DEFAULT 0 , 
		  "VALPRECOATACADO" DECIMAL(15,6) WITH DEFAULT 0 , 
		  "FLAGPERMITEOUTRODESC" CHAR(1) NOT NULL WITH DEFAULT 'F' , 
		  "DTCRIACAO" TIMESTAMP , 
		  "DTATUALIZACAO" TIMESTAMP , 
		  "FLAGCONSIDERAPRODUTOCADEIA" CHAR(1) NOT NULL WITH DEFAULT 'T' , 
		  "PERDESCONTOBASE" DECIMAL(15,6) WITH DEFAULT 0 )   
		 COMPRESS YES ADAPTIVE  
		 IN "USERSPACE1" LONG IN "LOBSPACE1"  
		 ORGANIZE BY ROW; 

COMMENT ON TABLE "DBA     "."PRODUTO_DESCONTO_QTDE" IS 'Armazena informaes de descontos aplicados sobre o preo do produto em vendas qdo a qtde dentro da faixa estabelecida.';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."DTALTERACAO" IS 'Data de alteracao do registro';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."DTATUALIZACAO" IS 'Data de atualizacao do Criterio Atacarejo de Off para On';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."DTCRIACAO" IS 'Data de criacao do Criterio Atacarejo';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."FLAGCONSIDERAPRODUTOCADEIA" IS 'Define se deve considerar os produtos da cadeia de preços para calculo do atacarejo.';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."FLAGPERMITEOUTRODESC" IS 'Define se sera permitido a aplicacao de outros descontos a esse criterio no momento da venda no CISSFront';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."IDCONTADOR" IS 'Contador sequencial';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."IDEMPRESA" IS 'Codigo da empresa';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."IDPRODUTO" IS 'Codigo interno do produto';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."IDSUBPRODUTO" IS 'Codigo do item derivado';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."IDUSUARIO" IS 'Codigo do usuario';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."INFOETIQUETA" IS 'Descricao exibida na etiqueta de preco';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."PERDESCONTO" IS '% desconto aplicado sobre o preco de venda do produto.';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."PERDESCONTOATAC" IS 'Campo para armazenar o desconto para preco tacado';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."PERDESCONTOBASE" IS '% desconto aplicado sobre o preco de venda do produto para formacao do preco psicologico.';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."QTDPRODUTO" IS 'Quantidade do produto';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."TIPODESCONTO" IS 'Identifica o tipo de desconto - "1  Acima de"", "2 - A Cada"", "9 - A Cada, considerando o maior desconto""';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."TIPOPRECOATACAREJO" IS 'Identificacao da sequencia de preco atacarejo configurada para o produto. 0-nao utiliza etiqueta atacarejo,1preco atacarejo 1,2preco atacarejo 2,3preco atacarejo 3,4preco atacarejo 4,5preco atacarejo 5';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."TIPOSTATUS" IS 'Status do cadastro. A-ativo, I-inativo ou U-alterado';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."VALPRECOATACADO" IS 'Campo para armazenar o Valor atacado';

COMMENT ON COLUMN "DBA     "."PRODUTO_DESCONTO_QTDE"."VALPRECOVAREJO" IS 'Valor do preco de varejo do produto';


